#!/usr/bin/env python3
"""Apply Android release hardening to a Flutter project generated by flutter create."""
from pathlib import Path
import re
import sys
import xml.etree.ElementTree as ET

if len(sys.argv) != 2:
    raise SystemExit("Usage: harden_android.py <flutter-project-directory>")

project = Path(sys.argv[1]).resolve()
android = project / "android"
manifest = android / "app/src/main/AndroidManifest.xml"
xml_dir = android / "app/src/main/res/xml"
gradle = android / "app/build.gradle.kts"

if not manifest.is_file():
    raise SystemExit(f"ERROR: Android manifest not found: {manifest}")
if not gradle.is_file():
    raise SystemExit(f"ERROR: Kotlin Gradle file not found: {gradle}")

xml_dir.mkdir(parents=True, exist_ok=True)
(xml_dir / "network_security_config.xml").write_text(
    '''<?xml version="1.0" encoding="utf-8"?>
<network-security-config>
    <base-config cleartextTrafficPermitted="false">
        <trust-anchors>
            <certificates src="system" />
        </trust-anchors>
    </base-config>
</network-security-config>
''',
    encoding="utf-8",
)

(xml_dir / "data_extraction_rules.xml").write_text(
    '''<?xml version="1.0" encoding="utf-8"?>
<data-extraction-rules>
    <cloud-backup>
        <exclude domain="root" path="." />
        <exclude domain="file" path="." />
        <exclude domain="database" path="." />
        <exclude domain="sharedpref" path="." />
        <exclude domain="external" path="." />
    </cloud-backup>
    <device-transfer>
        <exclude domain="root" path="." />
        <exclude domain="file" path="." />
        <exclude domain="database" path="." />
        <exclude domain="sharedpref" path="." />
        <exclude domain="external" path="." />
    </device-transfer>
</data-extraction-rules>
''',
    encoding="utf-8",
)

ET.register_namespace("android", "http://schemas.android.com/apk/res/android")
manifest_tree = ET.parse(manifest)
root = manifest_tree.getroot()
android_ns = "{http://schemas.android.com/apk/res/android}"
app = root.find("application")
if app is None:
    raise SystemExit("ERROR: Android manifest has no application element")
app.set(android_ns + "usesCleartextTraffic", "false")
app.set(android_ns + "networkSecurityConfig", "@xml/network_security_config")
app.set(android_ns + "allowBackup", "false")
app.set(android_ns + "fullBackupContent", "false")
app.set(android_ns + "dataExtractionRules", "@xml/data_extraction_rules")
ET.indent(manifest_tree, space="    ")
manifest_tree.write(manifest, encoding="utf-8", xml_declaration=True)

source = gradle.read_text(encoding="utf-8")
if "isMinifyEnabled = true" not in source:
    source, count = re.subn(
        r"(?m)^(\s*)release\s*\{",
        lambda m: (
            m.group(1) + "release {\n"
            + m.group(1) + "    isMinifyEnabled = true\n"
            + m.group(1) + "    isShrinkResources = true\n"
            + m.group(1) + '    proguardFiles(getDefaultProguardFile("proguard-android-optimize.txt"), "proguard-rules.pro")'
        ),
        source,
        count=1,
    )
    if count != 1:
        raise SystemExit("ERROR: could not safely find the Android release build type to enable R8")

if 'create("release")' not in source:
    match = re.search(r"(?m)^(\s*)buildTypes\s*\{", source)
    if not match:
        raise SystemExit("ERROR: could not safely find Android buildTypes in Gradle file")
    indent = match.group(1)
    signing = (
        indent + "signingConfigs {\n"
        + indent + '    create("release") {\n'
        + indent + '        val releaseStore = System.getenv("ANDROID_KEYSTORE_PATH")\n'
        + indent + "        if (releaseStore != null) {\n"
        + indent + "            storeFile = file(releaseStore)\n"
        + indent + "            storePassword = System.getenv(\"ANDROID_KEYSTORE_PASSWORD\")\n"
        + indent + "            keyAlias = System.getenv(\"ANDROID_KEY_ALIAS\")\n"
        + indent + "            keyPassword = System.getenv(\"ANDROID_KEY_PASSWORD\")\n"
        + indent + "        }\n"
        + indent + "    }\n"
        + indent + "}\n\n"
    )
    source = source[:match.start()] + signing + source[match.start():]

debug_signing = 'signingConfig = signingConfigs.getByName("debug")'
if debug_signing in source:
    source = source.replace(
        debug_signing,
        '''signingConfig = if (System.getenv("ANDROID_KEYSTORE_PATH") != null)
                    signingConfigs.getByName("release")
                else
                    signingConfigs.getByName("debug")''',
        1,
    )
elif "ANDROID_KEYSTORE_PATH" not in source:
    raise SystemExit("ERROR: could not safely configure release signing")

gradle.write_text(source, encoding="utf-8")
proguard = android / "app/proguard-rules.pro"
if not proguard.exists():
    proguard.write_text(
        "# Keep Flutter embedding and plugin entry points safe under R8.\n"
        "-keep class io.flutter.embedding.** { *; }\n"
        "-keep class io.flutter.plugin.** { *; }\n"
        "# Flutter references Play Store deferred-component classes that are not used by this APK.\n"
        "-dontwarn com.google.android.play.core.**\n",
        encoding="utf-8",
    )

# Always ensure the Flutter deferred-component references don't break R8 when
# Play Core split-install support isn't bundled. This APK does not use deferred components.
proguard = android / "app/proguard-rules.pro"
rules = proguard.read_text(encoding="utf-8")
if "-dontwarn com.google.android.play.core.**" not in rules:
    proguard.write_text(
        rules.rstrip() + "\n# Flutter references Play Store deferred-component APIs not used by this app.\n"
        "-dontwarn com.google.android.play.core.**\n",
        encoding="utf-8",
    )

print("Applied: HTTPS-only network policy, Android backup restrictions, R8 shrinking, and conditional release signing.")
